-- Importacao do catalogo ClinicusMed pra tabela conteudos
-- Gerado a partir do catalogo.json real -- 275 itens, em 6 lotes de ate 50
-- ciclo: semestre 1-5 = 'básico', semestre 6-10 = 'clínico' (ASSUNCAO -- confirmar se bate com a divisao real)

-- Lote 1/6
ON CONFLICT (slug) DO UPDATE SET
  titulo = EXCLUDED.titulo,
  disciplina = EXCLUDED.disciplina,
  ciclo = EXCLUDED.ciclo,
  descricao = EXCLUDED.descricao,
  premium = EXCLUDED.premium,
  file_url = EXCLUDED.file_url,
  semestre = EXCLUDED.semestre,
  etapa = EXCLUDED.etapa,
  updated_at = NOW();

